 assert_eq!(loaded,proposedids);let allsource:BTreeSet<u32>=rows.iter().flat_map(|c|c["ordered_source_ids"].as_array().unwrap()).filter(|v|!v.is_null()).map(id).collect();assert_eq!(allsource.len(),count("Source"));
 let foreign:BTreeSet<u32>=allsource.intersection(&baseids).copied().collect();let fallback:BTreeSet<u32>=allsource.difference(&baseids).copied().filter(|a|!own.contains(a)).collect();let active:BTreeSet<u32>=foreign.union(&own).copied().collect();assert_eq!(foreign.len(),count("foreign"));assert_eq!(fallback.len(),count("fallback"));assert_eq!(active.len(),count("Source"));
